syntax:
.box {
  width: 100px;
  padding: 10px;
  border: 1px solid;
  margin: 20px;
  box-sizing: border-box;
}

@keyframes bounce {
  50% { transform: translateY(-6px); }
}
.logo { animation: bounce 1s infinite; }

body {
  font-family: system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.6;
}

p { color: gray; }
.note { color: blue; }
#title { color: black; }

li:first-child { font-weight: bold; }
li:last-child { border: none; }
tr:nth-child(even) { background: #EEE; }

input:focus { outline: 2px solid blue; }
button:disabled { opacity: 0.5; }
li:not(.done) { color: black; }

.row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}

html { font-size: 16px; }
h1 { font-size: 2rem; }
p { line-height: 1.6; }

.title {
  font-weight: 700;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.cut {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
.loader { animation: spin 1s linear infinite; }

.doc { counter-reset: line; }
.row { counter-increment: line; }
.row::before { content: counter(line); }

@keyframes bounce {
  0%   { transform: translateY(0) scale(1); }
  30%  { transform: translateY(-5px) scale(1.12); }
  100% { transform: translateY(0) scale(1); }
}
a:hover > * { animation: bounce 0.6s ease; }

.lid {
  transform-origin: 4px 7.5px;
  transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.box:hover .lid { transform: rotate(-28deg); }

.bubble {
  opacity: 0;
  transition: opacity 0.2s;
}
a:hover .bubble {
  opacity: 1;
  transition-delay: 0.15s;
}

.has-bubble { position: relative; }
.bubble {
  position: absolute;
  top: calc(100% + 10px);
  left: 0;
}

#page {
  border: 0;
  background: none;
  outline: none;
  resize: none;
}
#page::placeholder { color: #A8A8A8; }

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
}
